lem-certificate.latex:
\begin{lemma}[{volume certificate}]\label{lem-certificate}
If \eqref{eq:2.4} holds, every feasible ellipsoid in \eqref{eq:2.3} satisfies
\begin{equation}\label{eq:2.5}
\operatorname{tr}(AM)\le n,\qquad
\det A\le\frac1{\det M}.
\end{equation}

\end{lemma}

lem-john.latex:
\begin{lemma}[{John's contact characterization \cite{John1948} and \cite[Theorems 3.1 and 3.3]{GG2007}}]\label{lem-john}
Let $K\subset\mathbb R^n$ be a convex body containing $B_2^n$.
Then $J(K)=B_2^n$ if and only if there are finitely many unit vectors
$u_i\in\partial K\cap S^{n-1}$ and positive weights $\lambda_i$ such that
\begin{equation}\label{eq:2.9}
u_i^Tx\le1\ (x\in K),\qquad
\sum_i\lambda_i u_i=0,\qquad
\sum_i\lambda_i u_i u_i^T=I,
\qquad \sum_i\lambda_i=n.
\end{equation}

\end{lemma}

prop-exact-duality.latex:
\begin{proposition}[{optimal multipliers from John contacts}]\label{prop-exact-duality}
Problems \eqref{eq:2.3} and \eqref{eq:2.8} attain their optima. If $\mathcal E(c,A)=J(\mathcal P)$, there are normalized dual multipliers with aggregate $M=A^{-1}$ and zero cone pairings. Hence the optimal values of \eqref{eq:2.3} and \eqref{eq:2.8} sum to zero.

\end{proposition}

prop-kkt.latex:
\begin{proposition}[{optimality and contact recovery}]\label{prop-kkt}
A feasible pair for \eqref{eq:2.3} and \eqref{eq:2.8} is optimal if and only if
\begin{equation}\label{eq:2.14}
M=A^{-1},\qquad
\alpha_r(\beta_r-g_r^Tc)-q_r^TAg_r=0\quad\text{for every }r.
\end{equation}

For each $\alpha_r>0$,
\begin{equation}\label{eq:2.15}
\beta_r-g_r^Tc=\|Ag_r\|,\qquad
q_r=\alpha_r\frac{Ag_r}{\|Ag_r\|}.
\end{equation}

With $p_r=Ag_r/\|Ag_r\|$ and $\mu_r=\alpha_r\|Ag_r\|$, the vectors and weights satisfy \eqref{eq:2.11}.

\end{proposition}

thm-sharp.latex:
\begin{theorem}[{sharp central-cut contraction}]\label{thm-sharp}
Let $K\subset\mathbb R^n$, $n\ge1$, be a convex body, and let $H$ be a closed halfspace whose boundary passes through $c(K)$. Then
\begin{equation}\label{eq:3.1}
w(K\cap H)\le R_nw(K),
\end{equation}
where $R_n$ is given by \eqref{eq:1.3}. For every fixed dimension, there are bodies and central cuts attaining equality.

\end{theorem}

thm-frame-bound.latex:
\begin{theorem}[{John-frame certificate bound}]\label{thm-frame-bound}
The matrix $Q$ is invertible with positive determinant. For $d=2-b$,
\begin{equation}\label{eq:3.12}
\frac{\chi}{1500}\le\log(R_n\det Q)\le\frac{\chi}{2d}.
\end{equation}

In particular, $\det Q\ge R_n^{-1}$. Equality in this determinant bound holds if and only if every contact has height $-1$ or $b$; then $Q=M_0$.

\end{theorem}

prop-gap.latex:
\begin{proposition}[{exact volume deficit}]\label{prop-gap}
In John coordinates, every feasible cut ellipsoid satisfies
\begin{equation}\label{eq:4.3}
\boxed{\epsilon:=\log\frac{R_n}{\det A}
=\Delta_{\rm geom}+\mathcal C+\mathcal D.}
\end{equation}

All three terms are nonnegative. For the actual new John ellipsoid, the same deficit is $\epsilon=\log(R_nw(K)/w(K\cap H))$ in the original coordinates.

\end{proposition}

lem-matching.latex:
\begin{lemma}[{matrix matching}]\label{lem-matching}
For any normalized feasible pair, if $G\le1/4$, then
\begin{equation}\label{eq:4.6}
\|M^{1/2}AM^{1/2}-I\|_F\le2\sqrt G.
\end{equation}

\end{lemma}

thm-equality.latex:
\begin{theorem}[{equality classification}]\label{thm-equality}
A normalized body $K$ attains $w(K\cap H_v)=R_nw(K)$ if and only if it admits a John frame supported on $\mathcal Z_b$ such that
\begin{equation}\label{eq:5.2}
\operatorname{conv}\bigl(B_2^n\cup\mathcal E(c_*,A_*)\bigr)
\subseteq K\subseteq P_{\mathcal U}.
\end{equation}

The new John ellipsoid is then exactly $\mathcal E(c_*,A_*)$. If equality holds, every positive-weight John frame supporting $K$ lies in $\mathcal Z_b$. For a contact polytope $P_{\mathcal U}$, equality is equivalent simply to its defining John frame being supported on $\mathcal Z_b$.

\end{theorem}

prop-extremizers.latex:
\begin{proposition}[{transverse construction}]\label{prop-extremizers}
Let unit vectors $w_i\in v^\perp$ and positive weights $\mu_i$ satisfy
$\sum_i\mu_iw_i=0$ and $\sum_i\mu_iw_iw_i^T=P$. Then the contacts
\begin{equation}\label{eq:5.7}
u_i=bv+\sqrt{1-b^2}\,w_i,\qquad
\lambda_i=\frac{\mu_i}{1-b^2},\qquad
u_{\rm pole}=-v,\qquad \lambda_{\rm pole}=\frac1{1+b}
\end{equation}
form a John frame supported on $\mathcal Z_b$.

\end{proposition}

lem-geometric-control.latex:
\begin{lemma}[{geometric control}]\label{lem-geometric-control}
For the explicit certificate,
\begin{equation}\label{eq:6.1}
\|Q-M_0\|_F^2\le\frac{1-b}{2-b}\chi,\qquad
\sum_i\lambda_i\operatorname{dist}(u_i,\mathcal Z_b)^2
\le\frac{32}{3}\chi.
\end{equation}

If $\chi\le3/2000$, then $\Delta_{\rm geom}\ge\chi/32$.

\end{lemma}

thm-stability.latex:
\begin{theorem}[{dimension-independent stability}]\label{thm-stability}
Let $\mathcal E(c,A)$ be any feasible cut ellipsoid in John coordinates, and assume
$0\le\epsilon=\log(R_n/\det A)\le10^{-6}$. Then
\begin{equation}\label{eq:6.2}
\begin{aligned}
\chi&\le32\epsilon,&
\|Q-M_0\|_F&\le4\sqrt\epsilon,\\
\|A-A_*\|_F&\le30\sqrt\epsilon,&
\|c-c_*\|&\le50\sqrt\epsilon,
\end{aligned}
\qquad
\sum_i\lambda_i\operatorname{dist}(u_i,\mathcal Z_b)^2
\le\frac{1024}{3}\epsilon.
\end{equation}

\end{theorem}

cor-iteration.latex:
\begin{corollary}[{successive exact central cuts}]\label{cor-iteration}
Suppose
$K_{j+1}=K_j\cap H_j$, where each cutting hyperplane passes through $c(K_j)$. Then
\begin{equation}\label{eq:7.1}
w(K_k)\le R_n^k w(K_0).
\end{equation}

If $K_0$ is contained in a ball of radius $R$ and all retained regions contain a target ball of radius $r>0$, then
\begin{equation}\label{eq:7.2}
k\le\frac{n\log(R/r)}{-\log R_n}.
\end{equation}

\end{corollary}

thm-determinant.latex:
\begin{theorem}[{quantitative John-frame determinant inequality}]\label{thm-determinant}
Every John frame in dimension $n\ge2$ satisfies
\begin{equation}\label{eq:8.4}
\frac{\chi}{1500}\le\log\det\widehat F\le\frac{\chi}{2d},
\qquad
\det F\ge\det F_0=\frac{d^{n+1}}{2^n(1-b)}.
\end{equation}

Equality in the determinant inequality holds if and only if $s_i\in\{-1,b\}$ for every contact, in which case $F=F_0$ and $\widehat F=I$.

\end{theorem}

lem-lifted-bound.latex:
